def solve(inp):
    h=len(inp); w=len(inp[0])
    ones=[(i,j) for i in range(h) for j in range(w) if inp[i][j]==1]
    rowsR={i for i,_ in ones}; colsC={j for _,j in ones}
    out=[r[:] for r in inp]
    import itertools
    # find connected components of 2
    seen=[[False]*w for _ in range(h)]; comps=[]
    for i in range(h):
        for j in range(w):
            if inp[i][j]==2 and not seen[i][j]:
                stack=[(i,j)]; comp=[]
                seen[i][j]=True
                while stack:
                    a,b=stack.pop(); comp.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<h and 0<=y<w and inp[x][y]==2 and not seen[x][y]:
                            seen[x][y]=True; stack.append((x,y))
                comps.append(comp)
    for comp in comps:
        rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
        hit=any(r in rowsR for r in rs) or any(c in colsC for c in cs)
        for a,b in comp: out[a][b]= 1 if hit else inp[a][b]
    return out
